sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    const selectTabId = event.payload.selectedTab.split('=')[1];
    if(selectTabId=="customer_history"){
        var ch_load_time = new Date().valueOf();
        api.setState("customerHistoryLoadedAt",ch_load_time);
    }
}
